// 先确认输入处于测试有效范围；范围判断也阻止非正常数值进入控制器。
xInputValid := NOT xSensorFault
    AND (rTarget_C >= 0.0) AND (rTarget_C <= 150.0)
    AND (rFeedback_C >= -50.0) AND (rFeedback_C <= 200.0);

// 故障保持锁存；只有反馈恢复有效且明确复位时才清除。
IF NOT xInputValid THEN
    xFault := TRUE;
ELSIF xReset THEN
    xFault := FALSE;
END_IF;

rActualSafe_C := 0.0;
rTargetSafe_C := 0.0;
IF xInputValid THEN
    rActualSafe_C := rFeedback_C;
    rTargetSafe_C := rTarget_C;
END_IF;

xSafeReset := NOT xEnable OR xReset OR xFault OR NOT xInitialized;

// 每个 10ms 周期只执行一次官方算法；停用和故障时复位积分并保持零输出。
fbPID(
    ACTUAL := rActualSafe_C,
    SET_POINT := rTargetSafe_C,
    KP := rKp,
    TN := rTn_s,
    TV := rTv_s,
    Y_MANUAL := 0.0,
    Y_OFFSET := 0.0,
    Y_MIN := 0.0,
    Y_MAX := 100.0,
    MANUAL := xSafeReset,
    RESET := xSafeReset,
    CYCLE := rCycle_s
);
xInitialized := TRUE;

// 当周期发现溢出或异常输出立即停热；下周期继续复位官方控制器。
IF fbPID.OVERFLOW OR NOT ((fbPID.Y >= 0.0) AND (fbPID.Y <= 100.0)) THEN
    xFault := TRUE;
END_IF;

rOutput_pct := 0.0;
xLimited := FALSE;
IF xEnable AND NOT xReset AND NOT xSafeReset AND NOT xFault THEN
    rOutput_pct := LIMIT(0.0, fbPID.Y, 100.0);
    xLimited := fbPID.LIMITS_ACTIVE;
END_IF;

// 仅测试模拟：一阶加热对象使用上一周期输出，所有变量都未映射实体 I/O。
IF xReset THEN
    rSimTemperature_C := rAmbient_C;
ELSIF xSimulate THEN
    rSimTemperature_C := rSimTemperature_C + rCycle_s / rPlantTau_s
        * (rAmbient_C + rPlantGain_C_per_pct * rOutput_pct - rSimTemperature_C);
END_IF;

IF xSimulate THEN
    rFeedback_C := rSimTemperature_C;
END_IF;

// MainTask 每 10ms 只调用本程序一次，本程序也只调用温控实例一次。
fbTemperature(
    rTarget_C := rTarget_C,
    rFeedback_C := rFeedback_C,
    xEnable := xEnable,
    xReset := xReset,
    xSensorFault := xSensorFault
